      by (clear - LO RNG ARE TPR SOR SBR PLCD; try acb; destruct RNG as [RNG']; destruct TPR as [TPR']; destruct SOR as [SOR']; destruct SBR as [SBR']; destruct PLCD as [PLCD'];
          unfold AHI_LO, AIMG_TOP, kSpaceSize in *;
